+    );
+
+    if (!nextPerson) {
+      alert("No citizens are waiting.");
+      return;
+    }
+
+    setCurrentToken(nextPerson);
+
+    setQueue((current) =>
+      current.map((item) =>
+        item.token === nextPerson.token
+          ? {
+              ...item,
+              status: "SERVING",
+            }
+          : item
+      )
+    );
+  };
+
